mapper.select:
SELECT asr.status AS tabFlag, count(1) AS count FROM approve_sync_record as asr WHERE asr.is_deleted=FALSE
${params.permissionSql}
GROUP BY asr.status

select asr.id as id, asr.create_user_id as createUserId, asr.create_user_name as createUserName, asr.create_time as createTime, asr.update_user_id as updateUserId, asr.update_user_name as updateUserName, asr.update_time as updateTime, asr.version as version, asr.is_deleted as isDeleted, asr.cfg_approve_sync_id as cfgApproveSyncId, asr.notice_type as noticeType, asr.business_type as businessType, asr.business_code as businessCode, asr.notice_method as noticeMethod, asr.receiver_id as receiverId, asr.receiver_name as receiverName, asr.send_time as sendTime, asr.title as title, asr.status as status, asr.error_reason as errorReason, asr.notice_node as noticeNode from approve_sync_record as asr WHERE ${params.sqlMap.default} AND asr.is_deleted = FALSE
and asr.id in
#{id}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
asr.create_time DESC
